import json
import re
import datetime

def cliniko(tool, args):
    return api.connectors.invoke(server="cliniko-scheduling", tool=tool, args=args) or {}

def link_id(obj, key):
    link = ((obj.get(key) or {}).get("links") or {}).get("self") or ""
    return link.rstrip("/").split("/")[-1] if link else ""

def parse(iso_str):
    return datetime.datetime.fromisoformat(iso_str.replace("Z", "+00:00"))

def zulu(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def read_json(path):
    try:
        return json.loads(api.files.read(file=path, scope="org") or "null")
    except Exception:
        return None

def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True), scope="org")

def comment(body):
    try:
        api.workq.comment(todo_id=todo_id, body=body)
    except Exception:
        pass

slug = str(params["slug"] or "")
todo_id = str(params["todo_id"] or "")
gap_slot = params["gap_slot"] or {}
decision = str(params["decision"] or "")
send_to = str(params.get("send_to") or "").strip()
notes = str(params.get("notes") or "").strip()

slot = gap_slot.get("slot") or {}
slot_label = str(gap_slot.get("slot_label") or "")
end_label = str(gap_slot.get("end_label") or "")
offers = [o for o in (gap_slot.get("offers") or []) if isinstance(o, dict) and o.get("email")]
recommended = [str(n) for n in (gap_slot.get("recommended") or [])]
settings = read_json("PracticeManager/Practices/" + slug + ".json") or {}
practice_name = str(settings.get("name") or "")
now = datetime.datetime.now(datetime.timezone.utc)
offers_path = "PracticeManager/State/" + slug + "-gap-offers-" + todo_id + ".json"

outcome = ""
sent = []
failed = []
skipped_numbers = []
note = ""

if decision == "Don't offer this slot":
    outcome = "rejected"
    try:
        api.workq.complete(todo_id=todo_id)
    except Exception:
        pass
elif read_json(offers_path):
    # The form was submitted again for a slot whose offers already went out --
    # never email the same patients twice.
    outcome = "already_sent"
    comment("Offers for this slot were already sent, so nothing was sent again.")
else:
    # Who gets it: blank = the recommended ones, "all" = everyone with a
    # drafted offer, otherwise the candidate numbers typed in.
    by_n = {str(o.get("n")): o for o in offers}
    if not send_to:
        chosen_ns = [n for n in recommended if n in by_n] or [str(o.get("n")) for o in offers[:1]]
    elif send_to.lower() == "all":
        chosen_ns = [str(o.get("n")) for o in offers]
    else:
        chosen_ns = []
        for n in re.findall(r"\d+", send_to):
            if n in by_n:
                if n not in chosen_ns:
                    chosen_ns.append(n)
            else:
                skipped_numbers.append(n)
    chosen = [by_n[n] for n in chosen_ns]

    # Still worth offering? The slot must be in the future and nobody can have
    # been booked into it since the item was raised.
    taken = False
    too_late = False
    try:
        start = parse(str(slot.get("starts_at") or ""))
        end = parse(str(slot.get("ends_at") or "")) if slot.get("ends_at") else start + datetime.timedelta(minutes=30)
        too_late = start <= now
    except Exception:
        start = None
        end = None
    practitioner_id = str(slot.get("practitioner_id") or "")
    if start and end and practitioner_id and not too_late:
        try:
            nearby = cliniko("list_individual_appointments", {
                "q": ["starts_at:>=" + zulu(start - datetime.timedelta(hours=4)), "starts_at:<" + zulu(end),
                      "practitioner_id:=" + practitioner_id],
                "per_page": 100,
            }).get("individual_appointments") or []
        except Exception:
            nearby = []
        for other in nearby:
            if other.get("cancelled_at") or other.get("archived_at") or other.get("deleted_at"):
                continue
            if link_id(other, "practitioner") != practitioner_id:
                continue
            try:
                if parse(str(other.get("starts_at") or "")) < end and parse(str(other.get("ends_at") or "")) > start:
                    taken = True
                    break
            except Exception:
                continue

    if too_late or not start:
        outcome = "too_late"
        comment("Nothing was sent: this slot has already started or passed.")
    elif taken:
        outcome = "taken"
        comment("Nothing was sent: someone has already been booked into this slot in Cliniko.")
    elif not chosen:
        outcome = "nobody"
        comment("Nothing was sent: no candidate matched \"" + send_to + "\". Enter numbers from the candidate list, \"all\", or leave it blank for the recommended ones, then submit the form again.")
    else:
        # One shared subject so the reply checker can match the patients'
        # replies ("RE: ...") back to this slot.
        subject = "Appointment available: " + slot_label + (" - " + practice_name if practice_name else "")
        for o in chosen:
            email_addr = str(o.get("email") or "")
            try:
                api.connectors.invoke(
                    server="m365-mail-send", tool="send_email",
                    args={"to": [email_addr], "subject": subject,
                          "body": str(o.get("offer_text") or ""), "contentType": "Text"},
                )
                sent.append(o)
            except Exception as exc:
                failed.append({"name": str(o.get("name") or ""), "email": email_addr, "error": str(exc)[:200]})
        outcome = "sent" if sent else "send_failed"

        if sent:
            # Handoff to the reply checker: who was offered the slot, and where
            # each one is booked now (a "later" patient is moved, not double-booked).
            write_json(offers_path, {
                "slug": slug,
                "todo_id": todo_id,
                "status": "awaiting_reply",
                "subject": subject,
                "sent_at": zulu(now),
                "slot": slot,
                "slot_label": slot_label,
                "end_label": end_label,
                "appointment_type_name": str(gap_slot.get("appointment_type_name") or ""),
                "offered": [{
                    "n": o.get("n"), "kind": o.get("kind"), "name": o.get("name"), "email": o.get("email"),
                    "patient_id": o.get("patient_id"), "appointment_id": o.get("appointment_id") or "",
                    "current_starts_at": o.get("current_starts_at") or "", "current_label": o.get("current_label") or "",
                } for o in sent],
                "notes": notes,
            })

        lines = ["Offer sent to: " + ", ".join(str(o.get("n")) + ". " + str(o.get("name") or "") + " (" + str(o.get("email") or "") + ")" for o in sent)] if sent else []
        if failed:
            lines.append("Couldn't send to: " + ", ".join(f["name"] + " (" + f["email"] + "): " + f["error"] for f in failed))
        if skipped_numbers:
            lines.append("Ignored number(s) not in the candidate list: " + ", ".join(skipped_numbers))
        if sent:
            lines.append("Waiting for the first patient to reply YES. This item stays open until the slot is filled.")
        comment("\n\n".join(lines))

# Audit trail (healthcare-practice-management-guardrail-audit format).
tz_name = str(settings.get("timezone") or "UTC")
try:
    from zoneinfo import ZoneInfo
    today_str = now.astimezone(ZoneInfo(tz_name)).date().isoformat()
except Exception:
    today_str = now.date().isoformat()
audit_path = "PracticeManager/AuditLog/" + slug + "-" + today_str + ".jsonl"
try:
    existing_log = api.files.read(file=audit_path, scope="org")
except Exception:
    existing_log = ""
audit_line = json.dumps({
    "ts": zulu(now),
    "practice_slug": slug,
    "actor": "agent",
    "source": "automation:Cliniko Automations: Send approved slot offers",
    "action": "sent" if outcome == "sent" else ("rejected" if outcome == "rejected" else "blocked"),
    "target": {"kind": "appointment_slot", "id": str(slot.get("key") or "")},
    "summary": "Freed slot " + slot_label + ": " + outcome + ("; offered to " + ", ".join(str(o.get("name") or "") for o in sent) if sent else ""),
    "guardrails": [{"rule": "patient_facing_requires_approval", "result": "pass", "detail": "sent only after the manager's form approval"}],
    "workq_item_id": todo_id,
}, sort_keys=True)
try:
    api.files.put(file=audit_path, content=existing_log + audit_line + "\n", scope="org")
except Exception:
    pass
